import { ref } from 'vue'
import {
  pointsApi,
  type PointsTransaction,
  type FilterType,
  type GetTransactionsResponse
} from '@/scripts/pointsApi'

interface PaginationState {
  page: number
  pageSize: number
  total: number
  totalPages: number
}

export function usePointsTransactions() {
  const transactions = ref<PointsTransaction[]>([])
  const loading = ref(false)
  const error = ref<string | null>(null)
  const pagination = ref<PaginationState>({
    page: 1,
    pageSize: 10,
    total: 0,
    totalPages: 0
  })

  async function fetchTransactions(
    page: number = 1,
    pageSize: number = 10,
    type: FilterType = 'all'
  ) {
    loading.value = true
    error.value = null
    try {
      const response = await pointsApi.getTransactions({ page, pageSize, type })
      transactions.value = response.transactions
      pagination.value = {
        page: response.page,
        pageSize: response.pageSize,
        total: response.total,
        totalPages: response.totalPages
      }
    } catch (e) {
      error.value = e instanceof Error ? e.message : 'Failed to fetch transactions'
    } finally {
      loading.value = false
    }
  }

  return { transactions, loading, error, pagination, fetchTransactions }
}
