<template>
  <div class="points-panel-container h-full">
    <div class="flex h-full flex-col">
      <h2 class="mb-2 text-2xl font-bold">{{ $t('points.title') }}</h2>
      <Divider class="mb-3" />

      <!-- 加载状态 -->
      <div v-if="loading" class="flex items-center justify-center py-8">
        <i class="pi pi-spin pi-spinner text-2xl text-muted" />
      </div>

      <!-- 未登录状态 -->
      <div v-else-if="!isLoggedIn" class="flex flex-col items-center gap-4 py-8">
        <i class="pi pi-lock text-4xl text-muted" />
        <p class="text-muted">{{ $t('points.pleaseLogin') }}</p>
        <Button @click="handleLogin">
          <i class="pi pi-sign-in" />
          {{ $t('login.login') }}
        </Button>
      </div>

      <!-- 已登录状态 -->
      <template v-else>
        <!-- 统计卡片 -->
        <div class="mb-4 grid grid-cols-3 gap-4">
          <!-- 当前余额 -->
          <div class="border-border bg-surface rounded-lg border p-4">
            <div class="mb-2 text-sm text-muted">{{ $t('points.currentBalance') }}</div>
            <div class="text-2xl font-bold text-primary">
              {{ stats.balance.toFixed(2) }}
            </div>
          </div>

          <!-- 累计获取 -->
          <div class="border-border bg-surface rounded-lg border p-4">
            <div class="mb-2 text-sm text-muted">{{ $t('points.totalEarned') }}</div>
            <div class="text-2xl font-bold text-green-500">
              +{{ stats.totalEarned.toFixed(2) }}
            </div>
          </div>

          <!-- 累计消耗 -->
          <div class="border-border bg-surface rounded-lg border p-4">
            <div class="mb-2 text-sm text-muted">{{ $t('points.totalConsumed') }}</div>
            <div class="text-2xl font-bold text-red-500">
              -{{ stats.totalConsumed.toFixed(2) }}
            </div>
          </div>
        </div>

        <!-- 筛选 -->
        <div class="mb-3 flex justify-end">
          <Select
            v-model="filterType"
            :options="filterOptions"
            option-label="label"
            option-value="value"
            :placeholder="$t('points.filterAll')"
          />
        </div>

        <Divider class="mb-3" />

        <!-- 交易记录表格 -->
        <PointsTransactionsTable ref="transactionsTableRef" :filter-type="filterType" />
      </template>
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import Divider from 'primevue/divider'
import Select from 'primevue/select'

import Button from '@/components/ui/button/Button.vue'
import PointsTransactionsTable from './PointsTransactionsTable.vue'
import { usePointsStats } from '@/composables/points/usePointsStats'
import { useUserStore } from '@/stores/userStore'
import { api } from '@/scripts/api'
import type { FilterType } from '@/scripts/pointsApi'

const { t } = useI18n()
const userStore = useUserStore()
const { stats, loading, fetchStats } = usePointsStats()

const isLoggedIn = ref(false)
const filterType = ref<FilterType>('all')
const transactionsTableRef = ref<InstanceType<typeof PointsTransactionsTable> | null>(null)

const filterOptions = computed(() => [
  { label: t('points.filterAll'), value: 'all' },
  { label: t('points.filterEarned'), value: 'earned' },
  { label: t('points.filterConsumed'), value: 'consumed' }
])

// 参考UserPanel的方式获取用户登录信息
async function checkLoginStatus() {
  loading.value = true
  try {
    const config = await api.getUserConfig()
    if (config?.users?.length) {
      isLoggedIn.value = true
      // 同步更新userStore
      if (!userStore.currentUserId) {
        userStore.login({
          userId: config.users[0].userId,
          username: config.users[0].username
        })
      }
      // 已登录，加载积分数据
      await fetchStats()
    } else {
      isLoggedIn.value = false
    }
  } catch (err) {
    console.error('Failed to check login status:', err)
    isLoggedIn.value = false
  } finally {
    loading.value = false
  }
}

// 初始化数据加载
onMounted(() => {
  void checkLoginStatus()
})

// 登录跳转处理
function handleLogin() {
  window.location.href = '/login'
}
</script>
