<template>
  <div>
    <!-- 加载状态 -->
    <div v-if="loading" class="flex items-center justify-center p-8">
      <ProgressSpinner />
    </div>

    <!-- 错误状态 -->
    <div v-else-if="error" class="p-4">
      <Message severity="error" :closable="false">{{ error }}</Message>
    </div>

    <!-- 空状态 -->
    <div v-else-if="transactions.length === 0" class="flex flex-col items-center justify-center p-8">
      <i class="pi pi-inbox mb-4 text-4xl text-muted" />
      <p class="text-muted">{{ $t('points.noRecords') }}</p>
    </div>

    <!-- 数据表格 -->
    <DataTable
      v-else
      :value="transactions"
      :paginator="true"
      :rows="pagination.pageSize"
      :total-records="pagination.total"
      :first="(pagination.page - 1) * pagination.pageSize"
      :lazy="true"
      class="p-datatable-sm custom-datatable"
      @page="onPageChange"
    >
      <!-- 类型列 -->
      <Column field="transactionType" :header="$t('points.type')">
        <template #body="{ data }">
          <Badge
            :value="getTransactionTypeLabel(data.transactionType)"
            :severity="getTransactionTypeSeverity(data.transactionType)"
          />
        </template>
      </Column>

      <!-- 金额列 -->
      <Column field="amount" :header="$t('points.amount')">
        <template #body="{ data }">
          <span :class="data.amount > 0 ? 'font-semibold text-green-500' : 'font-semibold text-red-500'">
            {{ data.amount > 0 ? '+' : '' }}{{ data.amount.toFixed(2) }}
          </span>
        </template>
      </Column>

      <!-- 时间列 -->
      <Column field="createTime" :header="$t('points.time')">
        <template #body="{ data }">
          {{ formatDate(data.createTime) }}
        </template>
      </Column>

      <!-- 备注列 -->
      <Column field="remark" :header="$t('points.remark')">
        <template #body="{ data }">
          <span class="text-sm text-muted">{{ data.remark || '-' }}</span>
        </template>
      </Column>
    </DataTable>
  </div>
</template>

<script setup lang="ts">
import { watch, onMounted } from 'vue'
import { useI18n } from 'vue-i18n'
import Badge from 'primevue/badge'
import Column from 'primevue/column'
import DataTable from 'primevue/datatable'
import Message from 'primevue/message'
import ProgressSpinner from 'primevue/progressspinner'

import { usePointsTransactions } from '@/composables/points/usePointsTransactions'
import type { FilterType } from '@/scripts/pointsApi'

const props = defineProps<{
  filterType: FilterType
}>()

const { t } = useI18n()
const { transactions, loading, error, pagination, fetchTransactions } = usePointsTransactions()

// 格式化日期
function formatDate(dateString: string): string {
  const date = new Date(dateString)
  return date.toLocaleString('zh-CN', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit'
  })
}

// 获取交易类型标签
function getTransactionTypeLabel(type: string): string {
  const typeMap: Record<string, string> = {
    'init': t('points.typeInit'),
    'recharge': t('points.typeRecharge'),
    'deduct': t('points.typeDeduct'),
    'daily_claim': t('points.typeDailyClaim')
  }
  return typeMap[type] || type
}

// 获取交易类型严重程度（用于Badge颜色）
function getTransactionTypeSeverity(type: string): 'success' | 'info' | 'warning' | 'secondary' {
  const severityMap: Record<string, 'success' | 'info' | 'warning' | 'secondary'> = {
    'init': 'info',
    'recharge': 'success',
    'deduct': 'warning',
    'daily_claim': 'success'
  }
  return severityMap[type] || 'secondary'
}

// 分页变更处理
function onPageChange(event: { page: number }) {
  fetchTransactions(
    event.page + 1,
    pagination.value.pageSize,
    props.filterType
  )
}

// 监听筛选类型变更
watch(() => props.filterType, () => {
  fetchTransactions(1, pagination.value.pageSize, props.filterType)
})

// 组件挂载时加载数据
onMounted(() => {
  fetchTransactions()
})

// 暴露刷新方法
defineExpose({
  refresh: () => fetchTransactions(1, pagination.value.pageSize, props.filterType)
})
</script>
